1	package docker
2	
3	import (
4		"os/exec"
5		"strings"
6	)
7	
8	// ContainerLaunchOptions holds parameters for running a container
9	type ContainerLaunchOptions struct {
10		Name        string   // container name (optional)
11		Image       string   // image to run
12		Entrypoint  string   // override default entrypoint (optional)
13		Ports       []string // "hostPort:containerPort"
14		Env         []string // "KEY=VALUE"
15		Volumes     []string // "name:/path"
16		Network     string   // network name
17		User        string   // user to run as (--user UID:GID or username, optional)
18		Detach      bool     // run in background (-d)
19		Remove      bool     // automatically remove the container when it exits (--rm)
20		Interactive bool     // keep STDIN open even if not attached (-i)
21		TTY         bool     // allocate a pseudo-TTY (-t)
22	}
23	
24	// noImplicitPull keeps `run` from fetching an image it does not have. Without
25	// it, launching a missing image is a pull no signature check saw (§3.82): an
26	// image reaches this machine through imagepull.Pull, or not at all. Measured on
27	// Docker and Podman: a missing image exits 125 with the engine's own message.
28	const noImplicitPull = "--pull=never"
29	
30	// buildLaunchArgs constructs the docker run argument list for the given options.
31	func buildLaunchArgs(opts ContainerLaunchOptions) []string {
32		args := []string{"run", noImplicitPull}
33		if opts.Remove {
34			args = append(args, "--rm")
35		}
36		if opts.Detach {
37			args = append(args, "-d")
38		}
39		if opts.Interactive {
40			args = append(args, "-i")
41		}
42		if opts.TTY {
43			args = append(args, "-t")
44		}
45		if opts.Name != "" {
46			args = append(args, "--name", opts.Name)
47		}
48		if opts.Entrypoint != "" {
49			args = append(args, "--entrypoint", opts.Entrypoint)
50		}
51		for _, p := range opts.Ports {
52			if p != "" {
53				args = append(args, "-p", p)
54			}
55		}
56		for _, e := range opts.Env {
57			if e != "" {
58				args = append(args, "-e", e)
59			}
60		}
61		for _, v := range opts.Volumes {
62			if v != "" {
63				args = append(args, "-v", v)
64			}
65		}
66		if opts.Network != "" {
67			args = append(args, "--network", opts.Network)
68		}
69		if opts.User != "" {
70			args = append(args, "--user", opts.User)
71		}
72		args = append(args, opts.Image)
73		return args
74	}
75	
76	// BuildLaunchCmd returns a ready-to-run exec.Cmd for the given options without executing it.
77	// Use this when you need to hand off the process to a terminal (e.g. tea.ExecProcess for -it mode).
78	func BuildLaunchCmd(opts ContainerLaunchOptions) (*exec.Cmd, error) {
79		if err := requireEngine(); err != nil {
80			return nil, err
81		}
82		return runner.Build(buildLaunchArgs(opts)...), nil
83	}
84	
85	// LaunchContainer runs a new container with the given options and returns its ID/output.
86	// Do NOT use this for interactive (-it) containers — use BuildLaunchCmd + tea.ExecProcess instead.
87	func LaunchContainer(opts ContainerLaunchOptions) (string, error) {
88		if err := requireEngine(); err != nil {
89			return "", err
90		}
91		output, err := dockerCombined(buildLaunchArgs(opts)...)
92		if err != nil {
93			return "", errWithOutput(cmdLabel("run"), output)
94		}
95		return strings.TrimSpace(string(output)), nil
96	}
97	
98	// VerifyEntrypoint checks if the given binary is available inside an image
99	// by running a short-lived throwaway container with /bin/sh -c "command -v <binary>".
100	// Returns true if the binary is found, false otherwise.
101	func VerifyEntrypoint(image, entrypoint string) (bool, error) {
102		if err := requireEngine(); err != nil {
103			return false, err
104		}
105		_, err := dockerCombined("run", noImplicitPull, "--rm", "--entrypoint", "/bin/sh",
106			image, "-c", "command -v "+entrypoint)
107		return err == nil, nil
108	}
