1	package docker
2	
3	import (
4		"context"
5		"fmt"
6		"log"
7		"strconv"
8		"strings"
9	)
10	
11	// Container represents a Docker container with its metrics
12	type Container struct {
13		ID        string
14		Name      string
15		Image     string
16		State     string // running, exited, paused, created, restarting, dead
17		Status    string // "Up 2 hours", "Exited (0) 5min ago"
18		CreatedAt string // "2 hours ago"
19		// Facts is what Status says, parsed once here so views never read
20		// Docker's wording. See ParseStatus.
21		Facts StatusFacts
22		// Ports is parsed here rather than carried as the string docker printed:
23		// the view must not learn to read Docker's output, and an opaque string
24		// cannot be searched by port number. See ParseContainerPorts.
25		Ports      []PortBinding
26		CPUPercent float64
27		MemUsage   string // "150MiB / 8GiB"
28		// MemBytes is the used half of MemUsage. It exists because MemPercent
29		// cannot be aggregated: it is a share of *this* container's limit, so two
30		// of them are fractions of different wholes (see Aggregate).
31		MemBytes   int64
32		MemPercent float64
33		NetIO      string // "1.2kB / 3.4kB"
34		NetRX      int64  // received bytes (parsed from NetIO)
35		NetTX      int64  // transmitted bytes (parsed from NetIO)
36		BlockIO    string // "1.2MB / 3.4MB"
37		BlockRX    int64  // block bytes read (parsed from BlockIO)
38		BlockTX    int64  // block bytes written (parsed from BlockIO)
39	}
40	
41	// ListContainers returns a list of containers. If all is true, includes stopped containers.
42	func ListContainers(all bool) ([]Container, error) {
43		// A nil context builds the command exactly as before (see dockerCmd.Ctx).
44		var noCtx context.Context
45		return ListContainersContext(noCtx, all)
46	}
47	
48	// parseContainers reads `ps` output built with templates().PS.
49	func parseContainers(output []byte) []Container {
50		var containers []Container
51		for _, line := range splitLines(output) {
52			parts := strings.SplitN(line, "\t", 7)
53			if len(parts) < 4 {
54				continue
55			}
56			c := Container{
57				ID:    parts[0],
58				Name:  parts[1],
59				Image: parts[2],
60				State: parts[3],
61			}
62			if len(parts) > 4 {
63				c.Status = parts[4]
64				c.Facts = ParseStatus(c.Status)
65			}
66			if len(parts) > 5 {
67				c.CreatedAt = parts[5]
68			}
69			if len(parts) > 6 {
70				c.Ports = ParseContainerPorts(parts[6])
71			}
72			containers = append(containers, c)
73		}
74	
75		return containers
76	}
77	
78	// GetContainerMetrics returns CPU/Memory/Net metrics for running containers
79	func GetContainerMetrics() (map[string]Container, error) {
80		if err := requireEngine(); err != nil {
81			return nil, err
82		}
83	
84		output, err := dockerOutput("stats", "--no-stream", "--format", templates().Stats)
85		if err != nil {
86			return nil, wrapErr(cmdLabel("stats"), err)
87		}
88	
89		metrics := make(map[string]Container)
90		for _, line := range splitLines(output) {
91			parts := strings.SplitN(line, "\t", 6)
92			if len(parts) < 5 {
93				continue
94			}
95	
96			cpu, _ := strconv.ParseFloat(strings.TrimSuffix(parts[1], "%"), 64)
97			mem, _ := strconv.ParseFloat(strings.TrimSuffix(parts[3], "%"), 64)
98			memBytes, _ := parsePair(parts[2])
99			netRX, netTX := parseNetIO(parts[4])
100	
101			var blockIO string
102			var blockRX, blockTX int64
103			if len(parts) >= 6 {
104				blockIO = parts[5]
105				blockRX, blockTX = parseNetIO(blockIO)
106			}
107			metrics[parts[0]] = Container{
108				ID:         parts[0],
109				CPUPercent: cpu,
110				MemUsage:   parts[2],
111				MemBytes:   memBytes,
112				MemPercent: mem,
113				NetIO:      parts[4],
114				NetRX:      netRX,
115				NetTX:      netTX,
116				BlockIO:    blockIO,
117				BlockRX:    blockRX,
118				BlockTX:    blockTX,
119			}
120		}
121	
122		return metrics, nil
123	}
124	
125	// Aggregate is what every running container adds up to, **on the daemon's
126	// scale**: both percentages run from 0 to 100, whatever the machine.
127	//
128	// That normalization is the whole of this type, and it exists because neither
129	// figure `docker stats` prints is one to begin with.
130	//
131	//   - `.CPUPerc` is relative to **one core**: Docker computes
132	//     `(cpuDelta/systemDelta) × onlineCPUs × 100`, so a container busy on two
133	//     cores reports 199% (measured, not assumed). Summed over the containers,
134	//     the raw total runs to `NCPU × 100` — 1400% on a sixteen-CPU daemon, which
135	//     is a true statement about fourteen cores and not a percentage of
136	//     anything. Divided by NCPU it becomes one.
137	//   - `.MemPerc` is relative to **that container's own limit**. Summing them
138	//     adds fractions of different wholes: a container capped at 256 MiB sitting
139	//     at 0.13% and one against the daemon's 15 GiB at 0.03% do not add up to
140	//     0.16% of anything. So the bytes are summed instead, over the daemon's own
141	//     total.
142	//
143	// It is measured *inside* the Docker VM on Windows and macOS, so it is still
144	// not addable with the host's numbers — it is a subset, and both dashboard
145	// sections say so in their title. What changes here is that the two are now at
146	// least in the same unit.
147	type Aggregate struct {
148		Available  bool
149		Running    int
150		CPUPercent float64
151		MemPercent float64
152	
153		// Cores is the daemon's CPU count, which is what CPUPercent was divided by.
154		// The dashboard prints it beside the figure for the same reason the host
155		// section prints its own: 40% of four cores and 40% of thirty-two do not
156		// describe the same machine.
157		Cores int
158	}
159	
160	// Capacity is what the daemon has to give, and therefore the denominator every
161	// percentage above is taken against.
162	type Capacity struct {
163		// Cores is `docker info`'s NCPU and MemTotal its memory, both as the
164		// *daemon* sees them — which on Windows and macOS is the VM's allocation
165		// and not the machine's. Reading the host's core count instead would be
166		// wrong on exactly the two platforms where Docker is not the host.
167		Cores    int
168		MemTotal int64
169	}
170	
171	// OK reports whether the capacity can serve as a denominator.
172	func (c Capacity) OK() bool { return c.Cores > 0 && c.MemTotal > 0 }
173	
174	// FetchCapacity reads what the daemon has, from `docker info`.
175	//
176	// It is read on every aggregate rather than memoized, and the 240 ms it costs
177	// (measured, against the 1–2 s `docker stats` already spends) is what buys it:
178	// a Docker Desktop reconfigured with a new CPU allocation changes this number
179	// under a running DevDesk, and a memo would divide by the old one for the life
180	// of the process — silently, since a wrong denominator still produces a
181	// plausible percentage.
182	func FetchCapacity() (Capacity, error) {
183		if err := requireEngine(); err != nil {
184			return Capacity{}, err
185		}
186		output, err := dockerOutput("info", "--format", templates().Info)
187		if err != nil {
188			return Capacity{}, wrapErr(cmdLabel("info"), err)
189		}
190	
191		fields := strings.SplitN(strings.TrimSpace(string(output)), "\t", 2)
192		if len(fields) < 2 {
193			return Capacity{}, fmt.Errorf("%s: unreadable capacity %q", cmdLabel("info"), output)
194		}
195		cores, err := strconv.Atoi(strings.TrimSpace(fields[0]))
196		if err != nil {
197			return Capacity{}, fmt.Errorf("%s: unreadable NCPU %q: %w", cmdLabel("info"), fields[0], err)
198		}
199		total, err := strconv.ParseInt(strings.TrimSpace(fields[1]), 10, 64)
200		if err != nil {
201			return Capacity{}, fmt.Errorf("%s: unreadable MemTotal %q: %w", cmdLabel("info"), fields[1], err)
202		}
203		return Capacity{Cores: cores, MemTotal: total}, nil
204	}
205	
206	// FetchAggregateMetrics reports what the running containers are using, as a
207	// share of what the daemon has.
208	//
209	// `docker stats --no-stream` costs about two seconds, measured: that is what
210	// earns it its own clock rather than a turn in the fast refresh.
211	//
212	// A capacity it cannot read makes the whole thing unavailable rather than a
213	// number on an unstated scale. That is the choice this function exists to make:
214	// the raw sums are not percentages, so there is nothing honest to show without
215	// their denominator — and `-` is a word this dashboard already has.
216	func FetchAggregateMetrics() Aggregate {
217		metrics, err := GetContainerMetrics()
218		if err != nil {
219			log.Printf("ERROR [docker] aggregate metrics: %v", err)
220			return Aggregate{}
221		}
222	
223		capacity, err := FetchCapacity()
224		if err != nil {
225			log.Printf("ERROR [docker] aggregate capacity: %v", err)
226			return Aggregate{}
227		}
228		if !capacity.OK() {
229			log.Printf("ERROR [docker] aggregate capacity: daemon reports %d cores and %d bytes",
230				capacity.Cores, capacity.MemTotal)
231			return Aggregate{}
232		}
233	
234		return aggregate(metrics, capacity)
235	}
236	
237	// aggregate is the arithmetic on its own, so a test can hand it readings rather
238	// than a daemon.
239	func aggregate(metrics map[string]Container, capacity Capacity) Aggregate {
240		agg := Aggregate{Available: true, Running: len(metrics), Cores: capacity.Cores}
241	
242		var memBytes int64
243		for _, c := range metrics {
244			agg.CPUPercent += c.CPUPercent
245			memBytes += c.MemBytes
246		}
247		agg.CPUPercent /= float64(capacity.Cores)
248		agg.MemPercent = float64(memBytes) / float64(capacity.MemTotal) * 100
249		return agg
250	}
251	
252	// StopContainer stops a container by ID
253	func StopContainer(id string) error {
254		return mutate(cmdLabel("stop"), "stop", id)
255	}
256	
257	// RestartContainer restarts a container by ID
258	func RestartContainer(id string) error {
259		return mutate(cmdLabel("restart"), "restart", id)
260	}
261	
262	// PauseContainer pauses a running container by ID
263	func PauseContainer(id string) error {
264		return mutate(cmdLabel("pause"), "pause", id)
265	}
266	
267	// UnpauseContainer resumes a paused container by ID
268	func UnpauseContainer(id string) error {
269		return mutate(cmdLabel("unpause"), "unpause", id)
270	}
271	
272	// RemoveContainer removes a container by ID. If force is true, uses -f flag.
273	func RemoveContainer(id string, force bool) error {
274		args := []string{"rm", id}
275		if force {
276			args = []string{"rm", "-f", id}
277		}
278		return mutate(cmdLabel("rm"), args...)
279	}
280	
281	// PruneContainers removes all stopped containers
282	func PruneContainers() (string, error) {
283		return prune(cmdLabel("container prune"), "container", "prune", "-f")
284	}
