286	// GetContainerLogs returns the last N lines of logs for a container.
287	// When timestamps is true, each line is prefixed with its RFC3339Nano timestamp.
288	func GetContainerLogs(id string, tail int, timestamps bool) (string, error) {
289		args := []string{"logs", "--tail", strconv.Itoa(tail)}
290		if timestamps {
291			args = append(args, "--timestamps")
292		}
293		args = append(args, id)
294	
295		output, err := dockerCombined(args...)
296		if err != nil {
297			return "", errWithOutput(cmdLabel("logs"), output)
298		}
299		return string(output), nil
300	}
301	
302	// InspectContainer returns the full `docker inspect` JSON for a container.
303	//
304	// The ID is validated rather than trusted: it reaches this from a table row,
305	// and a malformed one is a bug worth failing on rather than a string handed to
306	// a subprocess.
307	func InspectContainer(id string) ([]byte, error) {
308		if !IsContainerID(id) {
309			return nil, fmt.Errorf("%s failed: %q is not a container ID", cmdLabel("inspect"), id)
310		}
311		output, err := dockerCombined("inspect", id)
312		if err != nil {
313			return nil, errWithOutput(cmdLabel("inspect"), output)
314		}
315		return output, nil
316	}
317	
318	// ContainerStats contains Docker container counts
319	type ContainerStats struct {
320		Available bool
321		Running   int
322		Stopped   int
323		Paused    int
324	}
325	
326	// FetchContainerStats queries Docker for container status counts.
327	// Uses the docker CLI to avoid importing the heavy Docker SDK.
328	func FetchContainerStats() ContainerStats {
329		stats := ContainerStats{}
330	
331		if runner.LookPath() != nil {
332			return stats
333		}
334	
335		output, err := dockerOutput("ps", "-a", "--format", templates().PSState)
336		if err != nil {
337			return stats
338		}
339	
340		stats.Available = true
341	
342		for _, line := range splitLines(output) {
343			switch line {
344			case "running":
345				stats.Running++
346			case "paused":
347				stats.Paused++
348			default:
349				// exited, created, restarting, removing, dead
350				stats.Stopped++
351			}
352		}
353	
354		return stats
355	}
